#![allow(unused_imports)]
use vstd::*;

verus! {
    /// Given two positive 8-bit signed integers `x` and `y` as the inclusive bounds of
    /// an interval, returns the largest even integer in that interval, or `-1` if
    /// either the interval is empty (`x > y`) or contains no even integers.
    fn choose_num(x: i8, y: i8) -> i8 {
        // Empty interval
        if x > y {
            -1
        } else {
            // Start with the largest even ≤ y:
            //   if y is even, use y; otherwise use y - 1
            let e = if y % 2 == 0 { y } else { y - 1 };
            // If that even is still below x, there is no even in [x..y]
            if e < x {
                -1
            } else {
                // Otherwise, e is the largest even in [x..y]
                e
            }
        }
    }
}